parameters.jsCode:
const feed = $input.first().json;

// Find the EUR-EGP asset
const asset = feed.assets?.find(
  item => item.id === "EUR-EGP" && item.slug === "euro"
);

if (!asset) {
  throw new Error("EUR-EGP asset not found in API response");
}

// Extract the best rates for both directions
const sell = asset.directions?.sell?.best;
const buy = asset.directions?.buy?.best;

// Validate the returned rates
if (
  typeof sell?.value !== "number" ||
  typeof buy?.value !== "number"
) {
  throw new Error("Invalid EUR-EGP exchange rate values");
}

// Validate observation metadata
if (!asset.asOf || !asset.observedAt) {
  throw new Error("Missing exchange rate observation metadata");
}

// Return a clean data object
return [
  {
    json: {
      currencyPair: asset.id,
      unit: asset.unit,

      // You sell EUR to a bank
      youSellEurRate: sell.value,
      youSellEurBank: sell.seller,

      // You buy EUR from a bank
      youBuyEurRate: buy.value,
      youBuyEurBank: buy.seller,

      // Additional market references
      officialBuyBenchmark: asset.benchmark?.buy,
      officialSellBenchmark: asset.benchmark?.sell,
      globalRate: asset.global?.value,

      // Data quality
      asOf: asset.asOf,
      observedAt: asset.observedAt,
      freshness: asset.freshness?.state,
      isStale: asset.freshness?.stale,
      confidence: asset.confidence?.level,
      providers: asset.confidence?.providers,

      // Source attribution
      source: "Daleelak",
      sourceUrl: "https://getdaleelak.com/en/api"
    }
  }
];

const current = $('Extract & Validate EUR-EGP').first().json;
const previous = $input.first().json;

// Validate saved baseline
if (
  previous.currencyPair !== "EUR-EGP" ||
  typeof previous.youSellEurRate !== "number" ||
  typeof previous.youBuyEurRate !== "number"
) {
  throw new Error("Invalid or missing previous EUR-EGP rates");
}

// Calculate differences
const sellDifference = Number(
  (current.youSellEurRate - previous.youSellEurRate).toFixed(2)
);

const buyDifference = Number(
  (current.youBuyEurRate - previous.youBuyEurRate).toFixed(2)
);

// Detect changes
const sellChanged = sellDifference !== 0;
const buyChanged = buyDifference !== 0;

const rateChanged = sellChanged || buyChanged;

// Only allow notifications for fresh data
const isFresh =
  current.freshness === "fresh" &&
  current.isStale === false;

const shouldNotify = rateChanged && isFresh;

// Return comparison results
return [
  {
    json: {
      ...current,

      previousSellRate: previous.youSellEurRate,
      previousBuyRate: previous.youBuyEurRate,

      sellDifference,
      buyDifference,

      sellChanged,
      buyChanged,
      rateChanged,

      shouldNotify,

      decisionReason: !isFresh
        ? "Data is not fresh"
        : rateChanged
          ? "Exchange rate changed"
          : "No exchange rate change"
    }
  }
];

parameters.text:
=You are an exchange-rate market update assistant.

Analyze the following validated EUR-EGP exchange-rate data.

Currency pair: {{ $json.currencyPair }}

Previous rate when selling EUR: {{ $json.previousSellRate }}
Current rate when selling EUR: {{ $json.youSellEurRate }}
Change: {{ $json.sellDifference }}

Previous rate when buying EUR: {{ $json.previousBuyRate }}
Current rate when buying EUR: {{ $json.youBuyEurRate }}
Change: {{ $json.buyDifference }}

Best bank buying EUR: {{ $json.youSellEurBank }}
Best bank selling EUR: {{ $json.youBuyEurBank }}

Official buy benchmark: {{ $json.officialBuyBenchmark }}
Official sell benchmark: {{ $json.officialSellBenchmark }}

Observation date: {{ $json.asOf }}
Data freshness: {{ $json.freshness }}

Instructions:

1. Explain the exchange-rate movement in simple English.
2. Mention only the rates that changed.
3. Clearly explain whether EUR became more or less expensive in EGP.
4. Mention the relevant bank and its rate.
5. Keep the response under 80 words.
6. Do not invent values, calculate new exchange rates, predict future movements, or give financial advice.
7. State that rates are indicative.
